/* Draft legal text for the prototype.
   Sources: Reg Z Disclosures suite (files 01, 02, 04, 05, 07, 09, 12), Terms of Use vr4 specimen,
   Equifax consumer schedule, Prism Data addendum, and the Equifax and Launch consent review of 2026-10-09.
   Merge fields appear in [BRACKETS]. Paragraphs marked [NEW] were added for the Equifax, Prism and
   additional-information requirements and are for counsel review. Nothing here is approved for borrower use. */
window.LA_LEGAL = {

  esign: { title: "Electronic records and signatures consent", paras: [
    { h: "Consent to use electronic records and signatures", b: "Before you continue, please read this and tell us whether you agree. You cannot apply online unless you agree, but you can apply on paper instead. See section 2 below." },
    { h: "1. What you are agreeing to", b: "You agree that we may provide you with all records, disclosures, notices, and agreements relating to your loan application and your loan electronically, instead of on paper, and that you may sign them electronically.\n\nThis includes, but is not limited to:\n• Your Application and Solicitation Disclosure, Approval Disclosure, and Final Disclosure\n• Your Master Promissory Note and Credit Agreement\n• Your Self-Certification Form\n• Our Privacy Notice\n• Any notice about a decision on your application, including a notice explaining why we declined your application\n• Your automatic payment authorization, if you enroll\n• Statements, payment notices, and other communications about your loan after it is made\n• Any change to any of these\n\nYour consent applies to all of these records and to any other record we are required or allowed to provide you in writing during your application and the life of your loan. It is not limited to a single document or a single transaction." },
    { h: "Who \"we\" is [NEW]", b: "\"We\" and \"us\" include [CREDITOR_DBA] and our servicer, [SERVICER_NAME]." },
    { h: "2. Your right to get paper instead", b: "You have the right to receive any of these records on paper.\n• To get a paper copy of any record, contact us using the information in section 6. We will not charge you for it.\n• To apply on paper rather than online, contact us and we will send you a paper application package.\n\nAsking for a paper copy of a record does not withdraw your consent and does not change your loan." },
    { h: "3. Your right to withdraw your consent", b: "You may withdraw this consent at any time, at no cost and with no penalty.\n• To withdraw, contact us using the information in section 6.\n• We will confirm your withdrawal and begin sending you records on paper at the address we have on file.\n• Withdrawing your consent does not affect the validity of any record we already provided to you electronically, or of any document you already signed electronically, including your loan agreement.\n• If you withdraw your consent before your loan is made, we may not be able to continue your online application. We will tell you what your options are.\n• Your withdrawal takes effect once we have had a reasonable time to process it." },
    { h: "4. What you need in order to read and keep these records", b: "Internet connection: An active connection\nDevice: A computer, tablet, or smartphone\nBrowser: A current version of Chrome, Safari, Firefox, or Edge, with cookies enabled\nPDF reader: Software that can open PDF files\nEmail: A valid email address that you check, and the ability to receive email from us\nTo keep records: The ability to download and save files, or to print them\n\nIf these requirements change in a way that creates a material risk that you will not be able to access or keep your records, we will tell you and give you the chance to withdraw your consent at no cost and with no penalty.\n\nWe recommend that you download and save a copy of every record we provide, including your loan agreement." },
    { h: "5. Keeping your contact information current", b: "You must tell us promptly if your email address or mailing address changes. We will send electronic records to the email address you have given us, and paper records to the mailing address you have given us. To update your information, contact us using section 6." },
    { h: "6. How to contact us", b: "Request a paper copy: [ESIGN_CONTACT_METHOD]\nWithdraw your consent: [ESIGN_CONTACT_METHOD]\nUpdate your email or address: [ESIGN_CONTACT_METHOD]\n\n[CREDITOR_LEGAL_NAME] d/b/a [CREDITOR_DBA]\n[CREDITOR_ADDRESS]\n[CREDITOR_PHONE] | [CREDITOR_EMAIL]" },
    { h: "7. Your agreement", b: "By checking the box and selecting Continue, you confirm all of the following:\n• You have read and understood this Consent.\n• You can access and read this Consent on the device you are using now, and you are able to download or print it.\n• You have a valid email address and you can receive email from us at the address you gave us.\n• You agree to receive records electronically and to sign electronically, as described above.\n\nA copy of this Consent will be emailed to you and is available at any time in your account." }
  ] },

  paper: { title: "Apply on paper instead", paras: [
    { h: "You can", b: "You have the right to apply on paper. Contact us and we will send you a paper application package. We will not charge you for it. [Paper application process and contact details supplied by operations.]" }
  ] },

  terms: { title: "Terms of use and program terms", paras: [
    { h: "Draft status", b: "Specimen. Not for consumer use. Loans originated by [BANK PARTNER LEGAL NAME], Member FDIC." },
    { h: "1. These terms and your loan documents", b: "These Terms of Use and Program Terms (\"Terms\") govern your use of the LoanAmerica website, application portal, and borrower account (the \"Platform\"), operated by LoanAmerica (\"LoanAmerica,\" \"we,\" \"us\"). Loans offered through the Platform are made by [BANK PARTNER LEGAL NAME] (the \"Bank\"). Your loan is governed by your Loan Agreement and Promissory Note and your federal Truth in Lending disclosures, not by these Terms. If these Terms conflict with your loan documents, your loan documents control, and nothing in these Terms changes any term of your loan.\n\n[BANK-SUPPLIED PROGRAM LANGUAGE TO BE INSERTED HERE WITHOUT MODIFICATION] [Bank identification and program description]" },
    { h: "2. Eligibility", b: "To apply through the Platform you must: be at least 18 years old or the age of majority in your state; be a U.S. citizen or U.S. permanent resident; have a valid Social Security number; and be enrolled in or accepted to an eligible program at a participating school. Meeting these requirements does not guarantee approval; credit criteria apply." },
    { h: "3. Your account", b: "You agree to provide accurate, current, and complete information and to keep it updated. Keep your credentials confidential; you are responsible for activity under your account. Contact us immediately at [PHONE/EMAIL] about any unauthorized use. We may suspend Platform access to protect you or the program; suspension does not change your obligations or our obligations under any loan document." },
    { h: "4. Important information about opening an account", b: "To help the government fight the funding of terrorism and money laundering activities, federal law requires all financial institutions to obtain, verify, and record information that identifies each person who opens an account. What this means for you: when you apply, we will ask for your name, address, date of birth, and other information that allows us to identify you. We may also ask to see your driver's license or other identifying documents." },
    { h: "5. Communications", b: "By providing a telephone number, you agree that we, the Bank, and our service providers may contact you at that number about your application and account, including by autodialed or prerecorded calls and text messages. Consent to marketing calls and texts is not a condition of credit. You may revoke consent to autodialed or prerecorded calls and texts at any time by replying STOP to any text, by telling the agent on any call, or by contacting us at [PHONE/EMAIL], and we will honor your revocation promptly. Message and data rates may apply." },
    { h: "6. Electronic records and signatures", b: "Your Consent to Electronic Records and Signatures governs electronic delivery and signing and is part of these Terms. You may request free paper copies or withdraw that consent as described there." },
    { h: "7. Payments through the platform", b: "The Platform offers payment scheduling as a convenience. Your payment obligations are set by your Loan Agreement. You are never required to repay by preauthorized electronic debit; check and other payment methods are always available. Enrolling in automatic payments qualifies you for the interest rate discount described in your Loan Agreement." },
    { h: "8. Privacy", b: "Our Privacy Notice describes how we collect, use, and share your information. The Bank's privacy notice applies to your loan with the Bank. Both are provided to you no later than account opening.\n\n[BANK-SUPPLIED PROGRAM LANGUAGE TO BE INSERTED HERE WITHOUT MODIFICATION] [Bank privacy notice cross-reference]" },
    { h: "9. Questions and complaints", b: "Contact LoanAmerica at [PHONE], [EMAIL], or [ADDRESS]. We acknowledge complaints within [5] business days and respond within [15] business days. Complaints about your loan may also be submitted to the Bank and to the Consumer Financial Protection Bureau at consumerfinance.gov.\n\n[BANK-SUPPLIED PROGRAM LANGUAGE TO BE INSERTED HERE WITHOUT MODIFICATION] [Bank complaint escalation path and required regulator references]" },
    { h: "10. Acceptable use", b: "You agree not to: provide false information; access another person's account; interfere with the Platform's operation or security; or use the Platform unlawfully. We may terminate Platform access for violations; termination does not modify any loan." },
    { h: "11. Our content", b: "The Platform and its content belong to LoanAmerica or its licensors. We grant you a limited, personal, non-transferable license to use the Platform as intended. Educational content on the Platform is general information, not financial, legal, or tax advice." },
    { h: "12. Disclaimers and limits on liability", b: "The Platform is provided \"as is\" to the fullest extent permitted by applicable law. Nothing in these Terms waives or limits any right you have under federal or state consumer financial protection law, limits liability for our own fraud or willful misconduct, or limits the Bank's or LoanAmerica's obligations under your loan documents." },
    { h: "13. Changes to these terms", b: "We may update these Terms. We will give you at least 30 days' notice of material changes by email and Platform notice before they take effect. Changes never modify the terms of an existing loan. If you do not agree to updated Terms, you may stop using the Platform; your loan documents continue to govern your loan." },
    { h: "14. Disputes; governing law", b: "These Terms are governed by the law of [LENDER HOME STATE PER BANK CHARTER, TO MATCH THE LOAN AGREEMENT]. Disputes about your loan are subject to the dispute provisions of your Loan Agreement, including its arbitration section and your 60-day right to reject arbitration. Disputes solely about Platform use are subject to the same arbitration terms, with the same small claims carve-out and rejection right." },
    { h: "15. Contact", b: "LoanAmerica, [ADDRESS], [PHONE], [EMAIL]. Loans originated by [BANK PARTNER LEGAL NAME], Member FDIC." }
  ] },

  privacy: { title: "Privacy notice", paras: [
    { h: "FACTS: What does [CREDITOR_DBA] do with your personal information?", b: "Rev. [PRIVACY_NOTICE_VERSION_DATE]" },
    { h: "Why?", b: "Financial companies choose how they share your personal information. Federal law gives consumers the right to limit some but not all sharing. Federal law also requires us to tell you how we collect, share, and protect your personal information. Please read this notice carefully to understand what we do." },
    { h: "What?", b: "The types of personal information we collect and share depend on the product or service you have with us. This information can include:\n• Social Security number and date of birth\n• Income and employment information\n• Account balances and transaction history\n• Credit history and credit scores\n• Payment history\n• School enrollment and cost of attendance information\n\nWhen you are no longer our customer, we continue to share your information as described in this notice." },
    { h: "How?", b: "All financial companies need to share customers' personal information to run their everyday business. Below, we list the reasons financial companies can share their customers' personal information; the reasons [CREDITOR_DBA] chooses to share; and whether you can limit this sharing.\n\nFor our everyday business purposes, such as to process your transactions, maintain your accounts, respond to court orders and legal investigations, or report to credit bureaus: We share. You cannot limit this sharing.\n\nFor our marketing purposes, to offer our products and services to you: We share. You cannot limit this sharing.\n\nFor joint marketing with other financial companies: We do not share.\n\nFor our affiliates' everyday business purposes, information about your transactions and experiences: We do not share.\n\nFor our affiliates' everyday business purposes, information about your creditworthiness: We do not share.\n\nFor our affiliates to market to you: We do not share.\n\nFor nonaffiliates to market to you: We do not share." },
    { h: "Questions?", b: "Call [CREDITOR_PHONE] or go to [CREDITOR_WEBSITE]/privacy" },
    { h: "Who is providing this notice?", b: "[CREDITOR_LEGAL_NAME] d/b/a [CREDITOR_DBA]" },
    { h: "How does [CREDITOR_DBA] protect my personal information?", b: "To protect your personal information from unauthorized access and use, we use security measures that comply with federal law. These measures include computer safeguards and secured files and buildings. We limit access to your information to those employees and service providers who need it to do their jobs." },
    { h: "How does [CREDITOR_DBA] collect my personal information?", b: "We collect your personal information, for example, when you apply for a loan, give us your income information, connect a bank account so we can verify your income, make payments to us, or give us your contact information. We also collect your personal information from others, including credit bureaus, your school, and other companies." },
    { h: "Why can't I limit all sharing?", b: "Federal law gives you the right to limit only: sharing for affiliates' everyday business purposes, information about your creditworthiness; affiliates from using your information to market to you; and sharing for nonaffiliates to market to you. State laws and individual companies may give you additional rights to limit sharing. See Other important information below." },
    { h: "Definitions", b: "Affiliates: Companies related by common ownership or control. They can be financial and nonfinancial companies. Our affiliates include [AFFILIATE_LIST].\n\nNonaffiliates: Companies not related by common ownership or control. They can be financial and nonfinancial companies. [CREDITOR_DBA] does not share with nonaffiliates so they can market to you.\n\nJoint marketing: A formal agreement between nonaffiliated financial companies that together market financial products or services to you. [CREDITOR_DBA] doesn't jointly market." },
    { h: "Other important information", b: "For California residents: [CA_PRIVACY_SUPPLEMENT_REFERENCE]\nFor Vermont residents: [VT_LANGUAGE]\nFor Nevada residents: [NV_LANGUAGE]\nOther states: [STATE_PRIVACY_SUPPLEMENTS]" },
    { h: "Notice at collection of personal information (California residents)", b: "[CREDITOR_LEGAL_NAME] d/b/a [CREDITOR_DBA] collects the personal information described below. This notice applies to information that is not covered by the federal Gramm-Leach-Bliley Act. For information about how we handle your financial information, see our Privacy Notice at [CREDITOR_WEBSITE]/privacy.\n\nIdentifiers (name, email, phone, postal address, IP address, online identifiers): Used to respond to your inquiries; to send you information you requested; to market our products; to operate and secure our website. Retention: [RETENTION_IDENTIFIERS]\n\nCommercial information (products you inquired about, services you considered): Used to understand interest in our products and improve them. Retention: [RETENTION_COMMERCIAL]\n\nInternet or network activity (browsing on our site, pages viewed, referring site, interaction with our ads and emails): Used to operate, secure, and improve our website; to measure our marketing. Retention: [RETENTION_INTERNET]\n\nGeolocation data (approximate location from IP address): Used to determine whether we are able to offer loans in your state; fraud prevention. Retention: [RETENTION_GEO]\n\nProfessional or employment information (job title, employer, school role): Used to communicate with school and business contacts about partnerships. Retention: [RETENTION_PROFESSIONAL]\n\nInferences drawn from the above: Used to improve our marketing and our website. Retention: [RETENTION_INFERENCES]" },
    { h: "Sensitive information, selling and sharing, and your rights", b: "Sensitive personal information. [SENSITIVE_PI_STATEMENT]\n\nDo we sell or share your personal information? [SALE_SHARE_STATEMENT]\n\nYour rights. You have the right to know what personal information we collect, to delete it, to correct it, to limit our use of sensitive personal information, and to opt out of its sale or sharing. We will not discriminate against you for exercising these rights.\n\nTo exercise your rights: [CCPA_REQUEST_METHODS], or call [CCPA_TOLL_FREE].\n\nFull policy: [CREDITOR_WEBSITE]/privacy" }
  ] },

  h18: { title: "Application and solicitation disclosure", paras: [
    { h: "Private education loan, [PRODUCT_TIER_NAME] (Model Form H-18)", b: "[CREDITOR_LEGAL_NAME] d/b/a [CREDITOR_DBA]\n[CREDITOR_ADDRESS]\nDisclosure date: [DISCLOSURE_DATE] | Application ID: [APPLICATION_ID]\n[Creditor license disclosure lines are left out here and supplied by counsel.]" },
    { h: "Your interest rate (upon approval)", b: "The interest rate you pay will be determined after you apply. It will be based upon your credit history and other factors described in the Reference Notes below. If approved, we will notify you of the rate you qualify for within the stated range.\n\nYour interest rate range: [APR_RANGE_LOW]% to [APR_RANGE_HIGH]%\nRate type: [RATE_TYPE]" },
    { h: "Your interest rate during the life of the loan", b: "Your rate is fixed. This means that your rate will not change during the life of your loan. Your rate will not increase, and it will not decrease. [Fixed-rate version shown. A variable-rate version is drafted if one is ever offered.]" },
    { h: "Loan fees", b: "Application fee: [APPLICATION_FEE]\nOrigination fee: [ORIGINATION_FEE_DESCRIPTION]\nLate charge: [LATE_FEE_DESCRIPTION], assessed if a payment is more than [GRACE_PERIOD_DAYS] days late\nReturned payment charge: [NSF_FEE]\nPrepayment penalty: None. You may pay all or part of your loan early at any time without penalty.\n\nFee amounts may be lower in your state. The fees shown are the fees that apply to a loan made to a resident of [BORROWER_STATE]." },
    { h: "Loan cost examples", b: "The total amount you will pay for this loan will vary depending on when you start to repay it. This example provides estimates based upon the highest interest rate currently charged on this loan product and a $10,000 loan amount.\n\n1. Make full payments. Pay both the principal and interest amounts while enrolled in school and after leaving school. $10,000 at 17.99%, 60 months starting on disbursement. Total paid over life of loan: $15,232.79\n\n2. Pay only the interest. Make interest payments but defer payments on the principal amount while enrolled in school. $10,000 at 17.99%, 72 months (12 months in school, then 60 months). Total paid over life of loan: $17,031.79\n\n3. Defer payments. Make no payments while enrolled in school. Interest will be charged and added to your loan. $10,000 at 17.99%, 72 months (12 months in school, then 60 months). Total paid over life of loan: $17,973.17\n\nThe example figures above assume a 17.99% fixed rate, a $10,000 amount provided, no origination fee, and a 12 month in-school period for options 2 and 3. Option 3 assumes interest accrued during the in-school period is added to your principal balance (capitalized) once, at the start of repayment. Your actual amounts will differ. [Draft figures. Pricing fields are still being set.]" },
    { h: "Federal loan alternatives", b: "Direct Subsidized and Direct Unsubsidized Loans, U.S. Department of Education: [FED_UNDERGRAD_RATE] fixed, undergraduate students; [FED_GRAD_UNSUB_RATE] fixed, graduate and professional students (unsubsidized)\nDirect PLUS Loans, U.S. Department of Education: [FED_PLUS_RATE] fixed, parents and graduate or professional students\n\nRates shown apply to loans first disbursed during the [FED_RATE_AWARD_YEAR] award year. Federal loan interest rates are set annually and change each July 1.\n\nYou may qualify for Federal education loans. For additional information, contact your school's financial aid office or the U.S. Department of Education at www.studentaid.gov." },
    { h: "Next steps", b: "1. Find out about other loan options. Some schools have school-specific student loan benefits and terms not detailed on this form. Contact your school's financial aid office or visit the Department of Education's website at www.studentaid.gov for more information about other loans.\n\n2. To apply for this loan, complete the application and the Self-Certification Form. You may get the Self-Certification Form from your school's financial aid office, or we can provide it to you. If you are approved for this loan, the loan terms will be available to you for 30 days (terms will not change during this period, except as permitted by law)." },
    { h: "Reference notes: interest rate", b: "Your loan has a fixed interest rate. Interest is calculated on a simple interest basis and accrues daily on your outstanding principal balance beginning on the date your loan is disbursed." },
    { h: "Reference notes: eligibility criteria", b: "To be eligible for this loan you must:\n• Be enrolled, or accepted for enrollment, in an eligible program at a school we have approved for participation in this loan program;\n• Be at least 18 years of age, or the age of majority in your state of residence, at the time you sign your loan documents;\n• Be a U.S. citizen or permanent resident, or apply with a cosigner who is a U.S. citizen or permanent resident;\n• Be a resident of a state in which we are licensed to make this loan;\n• Meet our credit and income requirements, which are based primarily on your verified income and cash flow rather than on a minimum credit score. We do not require a minimum credit score.\n• Provide the financial account information we request so that we can verify your income, and authorize us to obtain and review your credit report;\n• Submit a signed Self-Certification Form; and\n• Have your enrollment and loan amount certified by your school before your loan is disbursed.\n\nYour school may not certify a loan amount greater than your cost of attendance minus your estimated financial assistance. Your loan amount is also limited by the maximum amount we approve for your loan tier and by the maximum amount established for your school's program." },
    { h: "Reference notes: interest capitalization", b: "If you choose an option that lets you postpone payments, interest will continue to be charged during that period. Any unpaid interest may be added to your principal balance at the end of that period. This is called capitalization. After interest is capitalized, you pay interest on the larger balance, which increases both your monthly payment and the total amount you pay. The Loan Cost Examples above show this effect. [Shown only if a deferral or interest-only option is offered.]" },
    { h: "Reference notes: cosigners", b: "You may apply with a cosigner. A cosigner may help you qualify or may help you qualify for a lower rate. A cosigner is fully responsible for repaying the entire loan. If you do not make your payments, we may seek payment from your cosigner, and the loan may appear on your cosigner's credit report and affect the cosigner's ability to obtain credit.\n\n[COSIGNER_RELEASE_LANGUAGE]" },
    { h: "Reference notes: bankruptcy", b: "[BANKRUPTCY_LANGUAGE]" },
    { h: "Reference notes: repayment terms and available loan amounts", b: "Loan amounts available: $[minimum] to [MAX_LOAN_AMOUNT]\nLoan term: [TERM_RANGE_LOW] to [TERM_RANGE_HIGH] months\nPayment frequency: Monthly, on the same day each month\nWhen repayment begins: [REPAYMENT_START_DESCRIPTION]\nPrepayment: Permitted at any time without penalty. Partial prepayments are applied first to accrued interest, then to principal.\nForbearance and deferral after repayment begins: May be available at our discretion for up to [FORBEARANCE_MAX_DAYS] days. Interest continues to accrue during any forbearance or deferral period." },
    { h: "Reference notes: more information, credit reporting, military borrowers", b: "The servicer of your loan will be [SERVICER_NAME]. You may contact the servicer at [SERVICER_CONTACT].\n\nWe report information about your loan to consumer reporting agencies. Late payments, missed payments, or other defaults on your loan may be reflected in your credit report and in your cosigner's credit report.\n\nIf you are an active duty servicemember or a dependent of an active duty servicemember, federal law may limit the interest rate and fees we may charge you and may give you additional rights. Contact us at [CREDITOR_PHONE] for more information." }
  ] },

  h19: { title: "Approval disclosure", paras: [
    { h: "Approval disclosure (Model Form H-19)", b: "[CREDITOR_LEGAL_NAME] d/b/a [CREDITOR_DBA] | [CREDITOR_PHONE]\n[CREDITOR_ADDRESS]\n[Creditor license disclosure lines are left out here and supplied by counsel.]\n\nBorrower: [BORROWER_NAME], [BORROWER_ADDRESS]\nCosigner: [COSIGNER_NAME]\nSchool: [SCHOOL_NAME]\nProgram: [PROGRAM_NAME]\nLoan ID: [LOAN_ID] | Date of this disclosure: [DISCLOSURE_DATE]" },
    { h: "Loan rate and estimated total costs", b: "Total Loan Amount: [TOTAL_LOAN_AMOUNT]\nInterest Rate: [INTEREST_RATE]% [RATE_TYPE]\nFinance Charge: [FINANCE_CHARGE]\nAnnual Percentage Rate (APR): [APR]%\nTotal of Payments: [TOTAL_OF_PAYMENTS]\n\nTotal Loan Amount is the amount of credit provided to you or on your behalf.\nInterest Rate is the cost of borrowing, expressed as a yearly rate.\nFinance Charge is the dollar amount the credit will cost you, including interest and fees.\nAnnual Percentage Rate (APR) is your cost over the term of the loan expressed as a rate. This rate may be higher than your Interest Rate because the APR includes certain fees and considers when the loan funds are disbursed. The APR is not the interest rate used to calculate your monthly payment.\nTotal of Payments is the total amount you will have paid when you have made all scheduled payments." },
    { h: "Itemization of amount financed", b: "Amount paid to your school on your behalf: [AMOUNT_TO_SCHOOL]\nAmount paid to you: [AMOUNT_TO_BORROWER]\nAmount paid to others on your behalf: [AMOUNT_TO_OTHERS]\nAmount Financed (total amount provided): [AMOUNT_FINANCED]\nLess prepaid finance charge (origination fee): ([PREPAID_FINANCE_CHARGE])\nTotal Loan Amount: [TOTAL_LOAN_AMOUNT]\n\nDisbursement schedule: [DISBURSEMENT_SCHEDULE]" },
    { h: "About this loan: interest rate", b: "Your interest rate is [INTEREST_RATE]% and is fixed. It will not change during the life of your loan. Interest accrues daily on your outstanding principal balance on a simple interest basis, beginning on the date your loan is disbursed." },
    { h: "Fees and default or late payment costs", b: "Origination fee: [ORIGINATION_FEE_DESCRIPTION]\nLate charge: [LATE_FEE_DESCRIPTION], if a payment is more than [GRACE_PERIOD_DAYS] days late\nReturned payment charge: [NSF_FEE]\nPrepayment penalty: None\nCollection costs: If you default, you may be required to pay costs of collection, including reasonable attorneys' fees, to the extent permitted by the law of [BORROWER_STATE]" },
    { h: "Estimated repayment schedule and terms", b: "[PERIOD_1_LABEL]: [INTEREST_RATE]%, [PERIOD_1_PAYMENT] monthly, [PERIOD_1_COUNT] payments, [PERIOD_1_TOTAL] paid in period\n[PERIOD_2_LABEL]: [INTEREST_RATE]%, [PERIOD_2_PAYMENT] monthly, [PERIOD_2_COUNT] payments, [PERIOD_2_TOTAL] paid in period\nTotal: [NUMBER_OF_PAYMENTS] payments, [TOTAL_OF_PAYMENTS]\n\nYour first payment is due [FIRST_PAYMENT_DATE]. Payments are due on the [PAYMENT_DUE_DAY] day of each month thereafter.\n\nRepayment options: [REPAYMENT_OPTIONS_DESCRIPTION]\n\nAutopay: [AUTOPAY_LANGUAGE]" },
    { h: "About your acceptance", b: "YOU HAVE UNTIL [ACCEPTANCE_DEADLINE] TO ACCEPT THIS OFFER.\n\nThe rate and terms of this loan will not change during this period, except for changes permitted by law. If you do not accept this offer by [ACCEPTANCE_DEADLINE], we may withdraw it, and you would need to reapply.\n\nHow to accept: [ACCEPTANCE_INSTRUCTIONS]" },
    { h: "Next steps", b: "1. Find out about other loan options. Contact your school's financial aid office or visit www.studentaid.gov for more information about other loans, including federal student loans, which may be available to you at lower cost.\n\nDirect Subsidized and Unsubsidized Loans, undergraduate: [FED_UNDERGRAD_RATE]\nDirect Unsubsidized Loans, graduate and professional: [FED_GRAD_UNSUB_RATE]\nDirect PLUS Loans: [FED_PLUS_RATE]\nRates apply to loans first disbursed during the [FED_RATE_AWARD_YEAR] award year. Federal rates change each July 1.\n\n2. Complete your Self-Certification Form. Before we can disburse this loan, we must receive your signed Private Education Loan Applicant Self-Certification Form. You may obtain the required cost of attendance and estimated financial assistance figures from your school's financial aid office.\n\n3. You have a right to cancel. You will have a right to cancel this loan without penalty after you accept it. After you accept, we will send you a Final Disclosure. You will then have until midnight of the third business day after you receive the Final Disclosure to cancel. We will not disburse any funds before that period ends." },
    { h: "Reference notes", b: "Prepayment: You may prepay all or part of this loan at any time without penalty. Partial prepayments are applied first to accrued interest, then to principal.\n\nCosigner: [COSIGNER_LANGUAGE] A cosigner is fully responsible for repaying the entire loan. [COSIGNER_RELEASE_LANGUAGE]\n\nBankruptcy: [BANKRUPTCY_LANGUAGE]\n\nServicer: Your loan will be serviced by [SERVICER_NAME], [SERVICER_CONTACT]. We will notify you if the servicer of your loan changes.\n\nCredit reporting: We report information about your loan to consumer reporting agencies. Late payments, missed payments, or other defaults may be reflected in your credit report and in your cosigner's credit report.\n\nMilitary borrowers: If you are a covered borrower under the Military Lending Act, federal law limits the military annual percentage rate we may charge and provides you additional protections, including protections regarding dispute resolution. Contact us at [CREDITOR_PHONE].\n\nQuestions: Contact [CREDITOR_DBA] at [CREDITOR_PHONE] or [CREDITOR_EMAIL]." }
  ] },

  h20: { title: "About your Final Disclosure", paras: [
    { h: "Right to cancel (Model Form H-20)", b: "You may cancel this loan, without penalty, at any time on or before [CANCELLATION_DEADLINE].\n\nNo funds will be disbursed to you or to your school until after [CANCELLATION_DEADLINE].\n\nTo cancel, contact us at [CANCELLATION_CONTACT_METHOD]. You do not need to give a reason." },
    { h: "When it arrives", b: "After you accept and sign, we send your Final Disclosure by text and email. You have until midnight of the third business day after you receive it to cancel. [Timing and wording to be confirmed by counsel against 12 CFR 1026.48.]" }
  ] },

  selfcert: { title: "Private education loan applicant self-certification", paras: [
    { h: "Form notice (OMB No. 1845-0101)", b: "Important: Pursuant to Section 155 of the Higher Education Act of 1965, as amended, (HEA) and to satisfy the requirements of Section 128(e)(3) of the Truth in Lending Act, a lender must obtain a self-certification signed by the applicant before disbursing a private education loan. The school is required on request to provide this form or the required information only for students admitted or enrolled at the school. Throughout this Applicant Self-Certification, \"you\" and \"your\" refer to the applicant who is applying for the loan. The applicant and the student may be the same person.\n\nInstructions: Before signing, carefully read the entire form, including the definitions and other information. Submit the signed form to your lender." },
    { h: "Section 1: Notices to applicant", b: "• Free or lower-cost Title IV federal, state, or school student financial aid may be available in place of, or in addition to, a private education loan. To apply for Title IV federal grants, loans and work-study, submit a Free Application for Federal Student Aid (FAFSA) available at www.fafsa.gov, or by calling 1-800-4-FED-AID, or from the school's financial aid office.\n• A private education loan may reduce eligibility for free or lower-cost federal, state, or school student financial aid.\n• You are STRONGLY encouraged to pursue the availability of free or lower-cost financial aid with the school's financial aid office.\n• The financial information required to complete this form can be obtained from the school's financial aid office. If the lender has provided this information, you should contact your school's financial aid office to verify this information and to discuss your financing options." },
    { h: "Section 2: Cost of attendance and estimated financial assistance", b: "A. Student's cost of attendance for the period of enrollment covered by the loan\nB. Estimated financial assistance for the period of enrollment covered by the loan\nC. Difference between amounts A and B\n\nWARNING: If you borrow more than the amount on line C, you risk reducing your eligibility for free or lower-cost federal, state, or school financial aid." },
    { h: "Section 4: Applicant signature", b: "I certify that I have read and understood the notices in Section 1 and, that to the best of my knowledge, the information provided on this form is true and correct." },
    { h: "Section 5: Definitions", b: "Cost of attendance is an estimate of tuition and fees, room and board, transportation, and other costs for the period of enrollment covered by the loan, as determined by the school. A student's cost of attendance may be obtained from the school's financial aid office.\n\nEstimated financial assistance is all federal, state, institutional (school), private, and other sources of assistance used in determining eligibility for most Title IV student financial aid, including amounts of financial assistance used to replace the expected family contribution. The student's estimated financial assistance is determined by the school and may be obtained from the school's financial aid office.\n\nA lender is a private education lender as defined in Section 140 of the Truth in Lending Act and any other person engaged in the business of securing, making, or extending private education loans on behalf of the lender.\n\nA period of enrollment is the academic year, academic term (such as semester, trimester, or quarter), or the number of weeks of instructional time for which the applicant is requesting the loan.\n\nA private education loan is a loan provided by a private education lender that is not a Title IV loan and that is issued expressly for postsecondary education expenses, regardless of whether the loan is provided through the school that the student attends or directly to the borrower from the private education lender. A private education loan does not include (1) an extension of credit under an open-end consumer credit plan, a reverse mortgage transaction, a residential mortgage transaction, or any other loan that is secured by real property or a dwelling; or (2) an extension of credit in which the school is the lender if the term of the extension of credit is 90 days or less or an interest rate will not be applied to the credit balance and the term of the extension of credit is one year or less, even if the credit is payable in more than four installments.\n\nTitle IV student financial aid includes the Federal Pell Grant Program, the Federal Supplemental Educational Opportunity Grant (FSEOG) Program, the Federal Work-Study (FWS) Program, the William D. Ford Federal Direct Loan (Direct Loan) Program, the Federal Perkins Loan Program, and the Teacher Education Assistance for College and Higher Education (TEACH) Grant Program. To apply for Title IV federal grants, loans, and work-study, submit a Free Application for Federal Student Aid (FAFSA), which is available at www.fafsa.gov, by calling 1-800-4-FED-AID, or from the school's financial aid office." },
    { h: "Section 6: Paperwork reduction notice", b: "According to the Paperwork Reduction Act of 1995, no persons are required to respond to a collection of information unless it displays a currently valid OMB control number. The valid OMB control number for this information collection is 1845-0101. The time required to complete this information collection is estimated to average 0.25 hours (15 minutes) per response, including the time to review instructions, search existing data resources, gather and maintain the data needed and complete and review the information collection.\n\nIf you have any comments concerning the accuracy of the time estimate(s) or suggestions for improving this form, please write to: U.S. Department of Education, Washington, DC 20202-4651. If you have any comments or concerns regarding the status of your individual submission of this form, contact your lender." }
  ] },

  mpn: { title: "Master promissory note and credit agreement", paras: [
    { h: "Where the full agreement goes", b: "[Insert the full Master Promissory Note and Credit Agreement, 27 sections, with Exhibit 1 Notice to Cosigner and Exhibit 2 State-Specific Notices.]" },
    { h: "What is in it", b: "1 Definitions. 2 Promise to pay. 3 How this master note works. 4 Amount of your loan, conditions, and disbursement. 5 Interest. 6 Repayment. 7 How we apply your payments. 8 Prepayment. 9 Late charges and other fees. 10 Your right to cancel. 11 Trouble making payments: forbearance and deferment. 12 Automatic payments (optional). 13 Default. 14 Acceleration. 15 Collection costs. 16 Credit reporting. 17 Cosigner obligations. 18 Communications. 19 Transfer of your loan. 20 Governing law. 21 Death and disability. 22 Military borrowers. 23 Dispute resolution. 24 Notice required by Federal Trade Commission rule. 25 Notices and electronic records. 26 Other terms. 27 Signatures." },
    { h: "16. Credit reporting", b: "16.1 We may report information about your account to consumer reporting agencies. Late payments, missed payments, or other defaults on your account may be reflected in your credit report and in your Cosigner's credit report.\n\n16.2 If you believe we have reported inaccurate information, notify us at [CREDITOR_DISPUTE_ADDRESS]. We will investigate and correct any inaccuracy as required by the Fair Credit Reporting Act.\n\n16.3 You authorize us to obtain consumer reports about you in connection with your application, and thereafter in connection with servicing, reviewing, collecting, or modifying your Loan." },
    { h: "18. Communications", b: "18.1 You authorize us, the Servicer, and our agents to contact you at any telephone number or email address you provide, including a mobile number, regarding your Loan.\n\n18.2 You may withdraw this authorization for calls and text messages at any time by notifying us as described in section 25. Withdrawing it will not affect our right to contact you by mail, or your obligations under this Agreement.\n\n18.3 Calls may be monitored or recorded for quality and training purposes." },
    { h: "23. Dispute resolution", b: "Option A, no arbitration clause (recommended in the draft): Any dispute arising out of this Agreement may be brought in any court of competent jurisdiction. You do not give up your right to a jury trial, and you do not give up your right to participate in a class action.\n\nOption B, arbitration clause: [ARBITRATION_CLAUSE]. Use only with counsel sign-off. This section does not apply to you if you are a covered borrower under the Military Lending Act." }
  ] },

  consentA: { title: "Credit and income verification", paras: [
    { h: "What you are allowing", b: "You authorize [CREDITOR_DBA], [SERVICER_NAME], and our agents to:\n• Obtain credit reports and credit scores about you from Equifax Information Services LLC (Equifax) and other consumer reporting agencies, now and while you have a loan with us, in order to evaluate your application, verify the information you gave us, and later to review, service, modify, or collect your loan.\n• Verify the information in your application, including your identity, income, employment, and school enrollment, with the sources you identified and with third parties." },
    { h: "Your written instructions [NEW]", b: "This is your written instruction for Equifax and other consumer reporting agencies to give your credit information to us for the purposes above. We will use it for no other purpose." },
    { h: "What happens to your credit score", b: "When you check your rate, we request your credit information from Equifax as a soft inquiry. A soft inquiry does not affect your credit score. When you accept your offer and submit your final application, we make a hard inquiry with Equifax, which may lower your credit score. [Confirm against the actual Equifax request configuration before use.]" },
    { h: "If we need more from you [NEW]", b: "If we cannot confirm your identity, income, employment, or school enrollment from what you gave us and from the sources above, we may ask you for more information or documents. For example, a photo ID, recent pay stubs or a tax return, bank statements, or proof of enrollment. You authorize us to request them, and to contact your employer, your school, or other sources you identified to confirm what you told us. If you do not provide what we ask for, we may not be able to finish reviewing your application." },
    { h: "If we decline your application", b: "We will tell you why. We will give you the name, address, and toll-free number of the consumer reporting agency, Equifax Information Services LLC, and you have the right to a free copy of your report from them within 60 days and to dispute anything inaccurate. [Confirm Equifax's current address and number before publishing.]" },
    { h: "Reporting your loan [NEW]", b: "We may report information about your loan, including payment history and any late or missed payments, to consumer reporting agencies, including Equifax." }
  ] },

  consentB: { title: "Connect your bank account", paras: [
    { h: "Why we ask", b: "We use the transaction history in your bank account to verify your income and to understand your monthly cash flow. This is how we can consider your application without relying only on a credit score." },
    { h: "What you are authorizing", b: "You authorize [CREDITOR_DBA], our service provider [BANK_DATA_PROVIDER], Equifax Information Services LLC (Equifax), and Equifax's analytics provider Prism Data Technologies, Inc. (Prism) [NEW] to access and use the following information from the bank account you connect:\n• Account ownership and account type\n• Account balances\n• Transaction history for the past [TRANSACTION_HISTORY_MONTHS] months, including deposits, withdrawals, and recurring payments" },
    { h: "What we use it for", b: "• Verify your income from recurring deposits\n• Identify your recurring monthly obligations\n• Calculate the cash flow score we use, together with other information, to decide your application and your rate. Equifax and Prism produce this score for us. [NEW]\n• [ACCOUNT_VALIDATION_USE_STATEMENT]" },
    { h: "How Equifax and Prism use it [NEW]", b: "We send your bank transaction information to Equifax and Prism so they can calculate your cash flow score. They may also use your information, after identifying details are removed or combined with other data, to test and improve their services. [Confirm the de-identification and permitted-use wording against the executed Prism Data Services Addendum.]" },
    { h: "What we do not do with it", b: "• We do not use it to make automatic withdrawals from your account. Setting up automatic payments is a separate, optional choice you make later, with its own authorization.\n• We do not sell it." },
    { h: "How long we have access", b: "[BANK_DATA_ACCESS_DURATION]" },
    { h: "How to disconnect", b: "You may disconnect your account at any time by [BANK_DATA_DISCONNECT_METHOD]. If you disconnect before we decide your application, we may not be able to finish reviewing it." },
    { h: "Your credentials", b: "When you connect your account, you enter your bank credentials directly with [BANK_DATA_PROVIDER]. [CREDITOR_DBA] does not see or store your bank username or password." },
    { h: "If you cannot connect your account [NEW]", b: "You can send us recent bank statements instead. [Alternate verification path to be confirmed.]" }
  ] },

  combined: { title: "What you're agreeing to", paras: [
    { h: "Paperwork online", b: "We'll send your application paperwork electronically, and you can sign it electronically. You can ask for paper copies any time at no cost, and you can take back your OK at any time. You'll need a phone or computer, a current browser, a PDF reader and an email you check. [Full electronic records and signatures consent to be shown or linked here.]" },
    { h: "Terms and privacy", b: "You agree to the Terms of Use. We've given you our Privacy Notice, which explains what we collect and who we share it with." },
    { h: "Calls and texts", b: "You authorize [CREDITOR_DBA], [SERVICER_NAME], and our service providers to call and text you at the number you gave us, about your application and your loan, including with automated dialing and prerecorded messages. Message and data rates may apply. You can take back this OK at any time by telling us. Offers and marketing are a separate, optional choice later." },
    { h: "Your school", b: "You authorize [SCHOOL_NAME] to share your enrollment status, program, cost of attendance and aid details with [CREDITOR_DBA] and its servicer, and you allow us to share what your school needs to certify your loan. This lasts until your loan is paid or your application is withdrawn or declined." },
    { h: "Not included here", b: "Your credit check and your bank connection each have their own step, with their own OK. [Counsel to confirm that these four items may be given in one consent.]" }
  ] },

  ccombined: { title: "What you're agreeing to", paras: [
    { h: "Paperwork online", b: "We'll send your cosigner paperwork electronically, and you can sign it electronically. You can ask for paper copies any time at no cost, and you can take back your OK at any time. You'll need a phone or computer, a current browser, a PDF reader and an email you check. [Full electronic records and signatures consent to be shown or linked here.]" },
    { h: "Terms and privacy", b: "You agree to the Terms of Use. We've given you our Privacy Notice, which explains what we collect and who we share it with." },
    { h: "Calls and texts", b: "You authorize [CREDITOR_DBA], [SERVICER_NAME], and our service providers to call and text you at the number you gave us about this loan, including with automated dialing and prerecorded messages. Message and data rates may apply. You can take back this OK at any time by telling us." },
    { h: "Nothing is final yet", b: "Agreeing here does not make you a cosigner. You'll get a separate notice and your own paperwork to read and sign later, and you can say no. [Counsel to confirm that these items may be given in one consent.]" }
  ] },

  consentC1: { title: "How we may contact you", paras: [
    { h: "About your application and your loan", b: "You authorize [CREDITOR_DBA], [SERVICER_NAME], and our agents to contact you about your application and your loan at the phone numbers and email addresses you give us, including a mobile number, using automated dialing, prerecorded messages, text messages, and email. Standard message and data rates may apply.\n\nThis includes calls and texts about your application status, your payments, your due dates, and your account. You may withdraw this consent at any time by telling us, by any reasonable method, that you no longer want to be contacted this way. Withdrawing it does not change what you owe, and we may still contact you by mail." }
  ] },

  consentC2: { title: "Offers and marketing (optional)", paras: [
    { h: "This is optional", b: "Your application is not affected by your answer, and declining will not change your rate, your terms, or our decision." },
    { h: "What you would get", b: "Calls, texts, and emails about other products, services, and offers from [CREDITOR_DBA]. You may opt out at any time by replying STOP to a text, using the unsubscribe link in an email, or calling [CREDITOR_PHONE]." }
  ] },

  consentD: { title: "Verify your enrollment with your school", paras: [
    { h: "Why we need this", b: "Before we can disburse your loan, your school must confirm that you are enrolled and must certify the amount of your loan. Federal law requires us to obtain a signed Self-Certification Form from you before we disburse a private education loan, and the cost of attendance and financial aid figures for that form come from your school's financial aid office. Your school also certifies your loan amount as a condition of our funding it." },
    { h: "What your school may release", b: "You authorize [SCHOOL_NAME] to release the following information about you to [CREDITOR_DBA] and its servicer, [SERVICER_NAME]:\n• Your enrollment status and the dates of your period of enrollment\n• Your program of study and its expected completion date\n• Your cost of attendance for the period covered by the loan\n• The amount of other financial aid you are receiving for that period\n• The loan amount your school certifies\n• Changes to any of the above, including if you withdraw, reduce your enrollment, or leave the program" },
    { h: "What we may share with your school", b: "You also authorize [CREDITOR_DBA] to give your school the information it needs to certify your loan, including your name, date of birth, the loan amount you requested, and your loan status." },
    { h: "How long this lasts", b: "This authorization stays in effect until your loan is paid in full or your application is withdrawn or declined." }
  ] },

  hard: { title: "Full credit check with Equifax", paras: [
    { h: "What you are allowing", b: "You authorize [CREDITOR_DBA] to make a hard inquiry with Equifax Information Services LLC so we can approve your loan. A hard inquiry may lower your credit score." },
    { h: "Your written instructions [NEW]", b: "This is your written instruction for Equifax to give us your credit information for this purpose. We will use it for no other purpose. [Confirm against the actual Equifax request configuration before use.]" }
  ] },

  ssn: { title: "Why we ask for your Social Security number", paras: [
    { h: "To confirm it's you", b: "Federal law requires lenders to verify who they are lending to." },
    { h: "To look up your credit", b: "For this step it's a soft check with Equifax, so your credit score stays the same." },
    { h: "A full check comes later", b: "If you choose to lock in your rate, we'll run a full credit check. We'll tell you before we do and ask for your OK." }
  ] },

  cosign: { title: "What cosigning means", paras: [
    { h: "They share the loan", b: "A cosigner promises to repay if the student can't. They are fully responsible, not just a backup." },
    { h: "It shows on their credit", b: "The loan appears on the cosigner's credit report." },
    { h: "It's their choice", b: "Nobody has to cosign. If they say no, nothing happens to them." },
    { h: "Their own notice", b: "Before they agree to anything, your cosigner gets a separate Notice to Cosigner and acknowledges it themselves." }
  ] },

  amount: { title: "How we estimate", paras: [
    { h: "Your school's number", b: "Your school sent us its estimate of what the year costs, including tuition, books and living costs." },
    { h: "Borrow less if you can", b: "Ask for any amount up to the estimate. Your school confirms the final amount before funds are sent. [Minimum amount set by program.]" }
  ] },

  income: { title: "What counts as income", paras: [
    { h: "Count it", b: "Pay from a job, tips, side work, and money you get regularly. A job offer that starts soon counts too." },
    { h: "Leave it out if you like", b: "You don't have to include alimony, child support or separate maintenance unless you want us to consider it." },
    { h: "Estimates are fine", b: "If we need to confirm your income, we'll ask later." }
  ] },

  federal: { title: "Check federal aid first", paras: [
    { h: "Why", b: "Federal student loans and grants can come with protections and repayment options that private loans do not." },
    { h: "Where to start", b: "Talk to your school's financial aid office or visit studentaid.gov, then borrow here only what you still need." }
  ] },

  nobank: { title: "If you can't connect your bank", paras: [
    { h: "No problem", b: "You can send us recent bank statements instead, and we may ask for other documents too. [Alternate verification path to be confirmed.]" },
    { h: "What it means", b: "Verifying by documents can take longer. We'll tell you what we need and keep your progress saved." }
  ] },

  whydocs: { title: "Why we're asking for more", paras: [
    { h: "What you agreed to", b: "When you allowed us to verify your information, you also allowed us to ask for more information or documents if we could not confirm what you told us from the sources we checked." },
    { h: "If you'd rather not", b: "You can stop at any time. If we don't get what we need, we may not be able to finish reviewing your application." }
  ] },

  cosignerNotice: {
    title: "Notice to cosigner",
    text: "You are being asked to guarantee this debt. Think carefully before you do. If the borrower doesn't pay the debt, you will have to. Be sure you can afford to pay if you have to, and that you want to accept this responsibility.\n\nYou may have to pay up to the full amount of the debt if the borrower does not pay. You may also have to pay late fees or collection costs, which increase this amount.\n\nThe creditor can collect this debt from you without first trying to collect from the borrower. The creditor can use the same collection methods against you that can be used against the borrower, such as suing you, garnishing your wages, etc. If this debt is ever in default, that fact may become a part of your credit record.\n\nThis notice is not the contract that makes you liable for the debt.",
    paras: [
      { h: "Required by 16 CFR 444.3", b: "You are being asked to guarantee this debt. Think carefully before you do. If the borrower doesn't pay the debt, you will have to. Be sure you can afford to pay if you have to, and that you want to accept this responsibility.\n\nYou may have to pay up to the full amount of the debt if the borrower does not pay. You may also have to pay late fees or collection costs, which increase this amount.\n\nThe creditor can collect this debt from you without first trying to collect from the borrower. The creditor can use the same collection methods against you that can be used against the borrower, such as suing you, garnishing your wages, etc. If this debt is ever in default, that fact may become a part of your credit record.\n\nThis notice is not the contract that makes you liable for the debt." }
    ]
  }
};
